function archiveItem(type,id){const list=type==='world'?'world':'connections',item=p()[list].find(x=>x.id===id);if(!item)return;mutate('Archived '+(item.name||item.label),pr=>{pr.archive.unshift({id:W.uid(),kind:type,title:item.name||item.label,created:new Date().toISOString(),item:W.copy(item)});pr[list]=pr[list].filter(x=>x.id!==id)})}
document.addEventListener('click',e=>{if(justDragged){e.preventDefault();return}if(brush&&!e.target.closest('.paint-tray,dialog')){const piece=e.target.closest('[data-paint]');if(piece){e.preventDefault();const color=brush;brush='';paint(piece.dataset.paint,piece.dataset.paintId,piece.dataset.paintCid,color);return}}const a=e.target.closest('[data-action],[data-nav]');if(!a)return;if(a.disabled)return;if(a.closest('form')&&a.type!=='submit')e.preventDefault();if(a.dataset.nav){navigate(a.dataset.nav);return}try{const result=actions[a.dataset.action]?.(a,e);if(result?.catch)result.catch(err=>{toast(err.message);console.error(err)});document.dispatchEvent(new CustomEvent('counterplot:action',{detail:{action:a.dataset.action,id:a.dataset.id||'',at:a.dataset.at||'',mode:sessionMode,project:workspace.active}}));}catch(err){toast(err.message);console.error(err)}});
document.addEventListener('keydown',e=>{if(e.target.closest('#tutorial-companion,[data-tutorial-ui]'))return;if((e.key==='Enter'||e.key===' ')&&e.target.matches('[role="button"][data-action]')){e.preventDefault();e.target.click();return}const typing=e.target.matches('input,textarea,select,[contenteditable]');if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();searchDialog()}else if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='z'&&!typing&&!$('#dialog').open){e.preventDefault();undo(e.shiftKey)}else if(e.key==='Escape'){if(brush){brush='';render()}if(ui.focus){ui.focus=false;render()}endDrag()}else if(e.key.toLowerCase()==='n'&&!typing&&!e.metaKey&&!e.ctrlKey&&!$('#dialog').open&&ui.page==='outline'){e.preventDefault();addPiece('B')}});
$('#dialog').addEventListener('cancel',e=>{e.preventDefault();closeDialog()});
document.addEventListener('submit',e=>{const form=e.target.closest('[data-form]');if(!form)return;e.preventDefault();const data=new FormData(form),v=k=>String(data.get(k)||'').trim(),m=modalData;try{
 if(form.dataset.form==='plot'){if(!v('label'))throw Error('Enter a plot label.');if((p().plots||[]).some(x=>x.id!==m.id&&x.label.toLowerCase()===v('label').toLowerCase()))throw Error('That label is already used.');if(mutate('Saved plot',()=>{p().plots||=[];const pl=p().plots.find(x=>x.id===m.id)||{id:W.uid()};Object.assign(pl,{label:v('label'),title:v('title'),notes:v('notes')});if(!m.id)p().plots.push(pl);})){closeDialog();}return;}
 if(form.dataset.form==='plot-membership'){if(mutate('Updated plot views',()=>W.assignPlot(p(),m.id,data.getAll('plots'),data.has('branch'))))closeDialog();return;}
 if(extraSubmit(form,data,m))return;
 if(form.dataset.form==='character'){if(!v('name'))throw Error('Give them a name or a working title.');const c=person(m.id)||W.character(v('name'));if(mutate(m.id?'Updated '+v('name'):'Created '+v('name'),pr=>{c.name=v('name');c.identity=v('identity');c.color=[...W.PALETTE,...(workspace.swatches||[])].some(s=>s.id===v('color'))?v('color'):'green';if(!m.id)pr.characters.push(c);ui.character=c.id;ui.at='';ui.page='characters'}))closeDialog();return}
 if(form.dataset.form==='block'){if(!v('text'))throw Error('Give the piece a few words first.');const c=person(m.cid),b=c.blocks.find(b=>b.id===m.bid)||W.block(m.kindId);if(mutate(m.bid?'Updated character piece':'Added '+kind(b.kind).label.toLowerCase(),()=>{b.color=v('color');for(const x of c.changes)if(x.blockId===b.id&&x.block)x.block.color=b.color;b.label=v('label');b.text=v('text');b.detail=v('detail');b.pinned=data.has('pinned');if(!m.bid)c.blocks.push(b);ui.character=c.id;ui.at='';ui.characterTab='blocks';ui.page='characters';ui.snap=b.id}))closeDialog();return}
 if(form.dataset.form==='change'){const c=person(m.cid),op=v('op'),at=v('at');if(!at)throw Error('Choose where this change happens.');if(op!=='retire'&&!v('text'))throw Error('Describe the new piece first.');const before=W.stateAt(p(),c,at).find(b=>b.id===m.bid);if(op!=='add'&&!before&&!m.changeId)throw Error('This piece is not present here. Choose a later moment, or add it to their starting blocks.');if(op==='add'&&before&&!m.changeId)throw Error('That piece is already present here.');if(c.changes.some(x=>x.id!==m.changeId&&x.blockId===m.bid&&x.at===at))throw Error('This block already changes at this moment. Edit that change in Their arc.');const b={...W.copy(m.block),text:v('text'),detail:v('detail')};if(m.isAdd)b.kind=v('newKind')||'custom';const x={id:m.changeId||W.uid(),at,blockId:m.bid,op,block:op==='retire'?null:b,reason:v('reason')};if(mutate('Kept a change for '+c.name,()=>{if(m.changeId)c.changes[c.changes.findIndex(x=>x.id===m.changeId)]=x;else c.changes.push(x);const n=node(at.split(':')[0]);if(n&&!n.cast.includes(c.id))n.cast.push(c.id);if(ui.page==='characters')ui.at=at;ui.snap=m.bid}))closeDialog();return}
 if(form.dataset.form==='move'){if(mutate('Moved outline piece',pr=>{W.move(pr,m.id,v('anchor'),v('where'));ui.snap=m.id;ui.folded.delete(v('anchor'))}))closeDialog();return}
 if(form.dataset.form==='links'){if(mutate('Updated story links',()=>{node(m.id)[m.kind==='cast'?'cast':'worldIds']=data.getAll('ids').map(String)}))closeDialog();return}
 if(form.dataset.form==='world'){if(!v('name'))throw Error('Give this detail a name.');const w=p().world.find(w=>w.id===m.id)||{id:W.uid()};if(mutate('Saved '+v('name'),pr=>{Object.assign(w,{name:v('name'),type:v('type'),notes:v('notes'),color:v('color')});if(!m.id)pr.world.push(w);if(m.linkNode){const target=pr.nodes.find(n=>n.id===m.linkNode);if(!target)throw Error('The thread is no longer available.');if(!target.worldIds.includes(w.id))target.worldIds.push(w.id)}}))closeDialog();return}
 if(form.dataset.form==='connection'){if(v('a')===v('b'))throw Error('Choose two different people.');if(!v('label'))throw Error('Give this connection a name.');const r=p().connections.find(r=>r.id===m.id)||{id:W.uid()};if(mutate('Saved connection',pr=>{Object.assign(r,{a:v('a'),b:v('b'),label:v('label'),notes:v('notes'),color:v('color')});if(!m.id)pr.connections.push(r)}))closeDialog();return}
 if(form.dataset.form==='project'){if(!v('title'))throw Error('Give the story a working title.');if(mutate(m.kind==='new-project'?'Opened a new story':'Renamed story',()=>{const pr=m.kind==='new-project'?W.project(v('title')):workspace.projects.find(p=>p.id===m.id)||p();pr.title=v('title');pr.subtitle=v('subtitle');if(m.kind==='new-project'){workspace.projects=workspace.projects.filter(p=>!W.shelfEmpty(p));workspace.projects.push(pr);workspace.active=pr.id;ui.at='';ui.folded.clear()}})){closeDialog();navigate('outline')}return}
}catch(error){formError(error)}});
function inlineUpdate(el){const d=el.dataset,target=d.inline==='node'?node(d.id):person(d.id);if(!target)return;if(!editBefore){editBefore=W.copy(workspace);editLabel=d.field==='prose'?'Edited prose':'Edited '+d.field}target[d.field]=el.value;if(d.inline==='node'&&d.field==='title'){const n=target;if(ui.selected===n.id&&$('.inspector h2')&&!$('.inspector h2 input'))$('.inspector h2').textContent=name(n);const card=$('[data-node="'+CSS.escape(n.id)+'"]');if(card){card.setAttribute('aria-label',W.TYPES[n.type].name+': '+name(n));card.querySelectorAll('[data-id="'+CSS.escape(n.id)+'"]').forEach(control=>{if(control.dataset.field&&['title','opening','closing'].includes(control.dataset.field))control.setAttribute('aria-label',({title:'Title',opening:n.type==='B'?'Plan':'Opening',closing:'Closing'}[control.dataset.field])+' · '+name(n));if(control.dataset.action==='archive-node')control.setAttribute('aria-label','Archive '+name(n));if(control.dataset.action==='select-node')control.setAttribute('aria-label','Edit details for '+name(n))})}}if(d.field==='prose'){if(!target.writingStatus)target.writingStatus='draft';}if(d.field==='prose'&&$('#word-count'))$('#word-count').textContent=words(el.value)+' words';if(d.field==='status'){finishEdit();render();return;}fit(el);const status=$('#save-status');if(status)status.innerHTML='<span class="save-dot"></span>Saving…';clearTimeout(saveTimer);saveTimer=setTimeout(save,250)}
function fit(el){if(el.tagName!=='TEXTAREA'||el.classList.contains('prose')||!el.dataset.inline)return;if(['opening','closing'].includes(el.dataset.field)){el.style.height='auto';el.style.height=Math.min(220,Math.max(24,el.scrollHeight))+'px'}}
function followPiece(target){
 if(ui.page!=='outline'||$('#dialog')?.open||drag)return;
 const card=target.closest?.('[data-node]');if(!card)return;
 const id=card.dataset.node;if(ui.selected===id)return;
 finishEdit();ui.selected=id;
 $$('.node.selected').forEach(el=>el.classList.remove('selected'));card.classList.add('selected');
 const panel=$('.inspector');if(panel)panel.outerHTML=inspector();
 // Selecting or typing on a card must not reopen a deliberately hidden inspector.

}
document.addEventListener('pointerdown',e=>followPiece(e.target));
document.addEventListener('focusin',e=>followPiece(e.target));
document.addEventListener('input',e=>{const el=e.target;if(el.dataset.inline)inlineUpdate(el);if(el.id==='shelf-search'){shelfQuery=el.value;$('#shelf-rows').innerHTML=shelfRows();}if(el.id==='archive-search')$('#archive-rows').innerHTML=archiveRows(el.value);if(['picker','hex'].includes(el.name)&&modalData?.kind==='swatch'){const hex=el.value;if(/^#[0-9a-f]{6}$/i.test(hex)){$('#dialog [name=picker]').value=hex;$('#dialog [name=hex]').value=hex;$('#swatch-preview').style.cssText=tokenStyle(hex)}}if(el.id==='kind-search')$('#kind-grid').innerHTML=kindTiles(el.value,modalData.group);if(el.id==='story-search')$('#search-results').innerHTML=searchResults(el.value)});
document.addEventListener('change',e=>{const el=e.target;if(el.dataset.inline){inlineUpdate(el);finishEdit()}if(el.id==='import-file')importFile(el.files[0]);if(el.id==='media-file')receiveImage(el.files[0]);if(el.name==='character'&&modalData?.kind==='choose-change')chooseChange(modalData.at,el.value);if(el.name==='op'&&modalData?.kind==='change')$('#change-text-fields').hidden=el.value==='retire';if(el.name==='at'&&modalData?.kind==='change'){const c=person(modalData.cid),b=W.stateAt(p(),c,el.value,true).find(b=>b.id===modalData.bid);$('#change-before').textContent=b?.text||'Not yet part of them'}});
document.addEventListener('focusout',e=>{if(e.target.dataset.inline)finishEdit()});
document.addEventListener('beforeinput',e=>{if(e.defaultPrevented||!['historyUndo','historyRedo'].includes(e.inputType)||e.target.closest('input,textarea,[contenteditable]:not([contenteditable="false"]),[data-tutorial-ui]'))return;e.preventDefault();undo(e.inputType==='historyRedo');});
window.addEventListener('pagehide',()=>{finishEdit();save();});
document.addEventListener('visibilitychange',()=>{if(document.hidden){finishEdit();save();}});
window.addEventListener('beforeunload',e=>{finishEdit();if(blocked||workspacePending()||sessionMode==='@author'||editorIsDirty()||unsavedSessionDrafts()){e.preventDefault();e.returnValue=''}});
window.addEventListener('storage',e=>{if(sessionMode!=='@author'&&e.key===KEY&&e.newValue!==lastSaved&&(e.newValue!==null||CounterplotTutorialStore.status().mode!=='indexeddb')){blocked='This story changed in another window. Export your work, then reload to see that copy.';saveBanner()}});
let landing=null,scrollFrame=0,dragY=0,touchDrag=null,ghost=null;
function startDrag(el){finishEdit();drag={type:el.dataset.drag,id:el.dataset.dragId,cid:el.dataset.cid||''};document.body.classList.add('drag-active');el.classList.add('dragging');const hint=$('#drag-hint');if(hint)hint.textContent=drag.type==='swatch'?'Drop onto any piece to give it this color':drag.type==='palette'?'Drop into a gap, or inside a thread':drag.type==='character'?'Drop into a thread or beat to add them':drag.type==='block'?'Drop onto a story moment to let this change':'Move the whole branch. Look for the landing slot.';return drag}
function findDrop(target){if(!drag)return null;if(drag.type==='swatch')return target?.closest?.('[data-paint]')||null;let el=target?.closest?.('[data-drop]');while(el){const type=el.dataset.drop;if(drag.type==='block'&&type==='block'&&el.dataset.cid===drag.cid&&!ui.at)return el;if(drag.type==='block'&&(type==='moment'||type==='node'))return el;if(drag.type==='character'&&(type==='node'||type==='moment'))return el;if((drag.type==='node'||drag.type==='palette')&&['position','node','archive'].includes(type)){if(type==='archive'&&drag.type!=='node')return null;const id=el.dataset.anchor;if(drag.type==='node'&&(id===drag.id||W.descendants(p(),drag.id).has(id)))return null;return el}el=el.parentElement?.closest('[data-drop]')}return null}
function highlight(el){if(landing===el)return;landing?.classList.remove('landing');landing=el;landing?.classList.add('landing');if(landing?.dataset.drop==='position'){const label=landing.querySelector('.slot-label');if(label)label.textContent=landing.dataset.where==='inside'?(landing.dataset.anchor?'Release inside this thread':'Release in the outer outline'):'Release '+landing.dataset.where+' this piece'}}
function autoScroll(){if(!drag){scrollFrame=0;return}const margin=90,delta=dragY<margin?-Math.ceil((margin-dragY)/7):dragY>innerHeight-margin?Math.ceil((dragY-innerHeight+margin)/7):0;if(delta)window.scrollBy(0,delta);scrollFrame=requestAnimationFrame(autoScroll)}
function endDrag(){drag=null;touchDrag=null;highlight(null);document.body.classList.remove('drag-active');$$('.dragging').forEach(el=>el.classList.remove('dragging'));const hint=$('#drag-hint');if(hint)hint.textContent='';cancelAnimationFrame(scrollFrame);scrollFrame=0;ghost?.remove();ghost=null}
function dropPiece(payload,el){if(!el||!payload)return;const d=el.dataset,anchor=d.anchor||'',type=payload.type,id=payload.id;
 if(type==='swatch'){paint(d.paint,d.paintId,d.paintCid,id);return}
 if(d.drop==='archive'){if(type==='node'){const n=node(id);if(n)mutate('Archived '+name(n),pr=>W.archiveNode(pr,id))}return}
 if(type==='character'){const n=node(anchor||d.at?.split(':')[0]);if(!n||!person(id))return;if(n.cast.includes(id)){toast(person(id).name+' is already in this piece.');return}mutate('Added '+person(id).name+' to '+name(n),()=>{n.cast.push(id);ui.selected=n.id;ui.snap=n.id});return}
 if(type==='block'){if(d.drop==='block'){const c=person(payload.cid),from=c.blocks.findIndex(b=>b.id===id),to=c.blocks.findIndex(b=>b.id===anchor);if(from<0||to<0||from===to)return;mutate('Rearranged character pieces',()=>{const [b]=c.blocks.splice(from,1);c.blocks.splice(to,0,b);ui.snap=b.id});return}const at=d.at||anchor+':open',existing=person(payload.cid)?.changes.find(x=>x.at===at&&x.blockId===id);editChange(payload.cid,id,at,existing?.id||'');return}
 const target=node(anchor),where=d.drop==='node'?(target?.type==='B'?'after':'inside'):d.where||'inside';
 if(type==='palette'){addPiece(id,'',anchor,where);return}
 if(type==='node')mutate('Moved '+name(node(id)),pr=>{W.move(pr,id,anchor,where);ui.selected=id;ui.snap=id;ui.folded.delete(anchor)});
}
document.addEventListener('dragstart',e=>{const el=e.target.closest('[data-drag]');if(!el)return;if(touchDrag){e.preventDefault();return}startDrag(el);e.dataTransfer.effectAllowed=drag.type==='palette'?'copy':'move';e.dataTransfer.setData('text/plain','Counterplot piece');e.dataTransfer.setData('application/x-counterplot',JSON.stringify(drag));dragY=e.clientY;if(!scrollFrame)scrollFrame=requestAnimationFrame(autoScroll)});
document.addEventListener('dragover',e=>{if(!drag)return;dragY=e.clientY;const target=findDrop(e.target);highlight(target);if(target){e.preventDefault();e.dataTransfer.dropEffect=drag.type==='palette'?'copy':'move'}});
document.addEventListener('drop',e=>{if(!drag)return;e.preventDefault();const payload={...drag},target=landing||findDrop(e.target);endDrag();justDragged=true;setTimeout(()=>justDragged=false,150);try{dropPiece(payload,target)}catch(err){toast(err.message)}});
document.addEventListener('dragend',endDrag);
document.addEventListener('pointerdown',e=>{if(e.button!==0)return;const el=e.target.closest('[data-drag]');if(!el)return;touchDrag={el,x:e.clientX,y:e.clientY,id:e.pointerId,started:false}});
document.addEventListener('pointermove',e=>{if(!touchDrag||e.pointerId!==touchDrag.id)return;if(!touchDrag.started&&Math.hypot(e.clientX-touchDrag.x,e.clientY-touchDrag.y)>10){touchDrag.started=true;startDrag(touchDrag.el);ghost=document.createElement('div');ghost.className='drag-ghost';ghost.textContent=drag.type==='swatch'?'Paint · '+swatches().find(s=>s.id===drag.id)?.name:drag.type==='palette'?W.TYPES[drag.id].name:drag.type==='character'?person(drag.id)?.name:drag.type==='node'?name(node(drag.id)):'Character piece';document.body.append(ghost);if(!scrollFrame)scrollFrame=requestAnimationFrame(autoScroll)}if(touchDrag?.started){e.preventDefault();dragY=e.clientY;ghost.style.left=e.clientX+'px';ghost.style.top=e.clientY+'px';highlight(findDrop(document.elementFromPoint(e.clientX,e.clientY)))}},{passive:false});
document.addEventListener('pointerup',e=>{if(!touchDrag||e.pointerId!==touchDrag.id)return;if(touchDrag.started){e.preventDefault();const payload={...drag},target=landing||findDrop(document.elementFromPoint(e.clientX,e.clientY));endDrag();justDragged=true;setTimeout(()=>justDragged=false,200);try{dropPiece(payload,target)}catch(err){toast(err.message)}}else touchDrag=null});
